    /*
     * Add to the MaintenanceRecords
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Aircraft
     */
    public Aircraft addToMaintenanceRecords( UUID parentId, MaintenanceWorkOrder addTo ) {
	    LOGGER.info("handling AssignMaintenanceRecordsToAircraftEvent - " );
	    
	    Aircraft parentEntity = repository.findById(parentId).get();
	    MaintenanceWorkOrder child = registry.project( MaintenanceWorkOrder.class, addTo.getMaintenanceWorkOrderId());
	    
	    parentEntity.getMaintenanceRecords().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the MaintenanceRecords
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Aircraft
     */
	public Aircraft removeFromMaintenanceRecords( UUID parentId, MaintenanceWorkOrder removeFrom ) {
	    LOGGER.info("handling RemoveMaintenanceRecordsFromAircraftEvent " );
	
	    Aircraft parentEntity = repository.findById(parentId).get();
	    MaintenanceWorkOrder child = registry.project( MaintenanceWorkOrder.class, removeFrom.getMaintenanceWorkOrderId());
	    
	    parentEntity.getMaintenanceRecords().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



